self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(async()=>{try{const r=await fetch(new URL('./audio/sfx/manifest.json',self.location.href));if(r.ok){const data=await r.json(),cache=await caches.open(CACHE);for(const file of data.files??[])if(['yay.mp3','applause.mp3','meow.mp3','purr.mp3'].includes(file)){try{await cache.add('./audio/sfx/'+file);}catch{}}}}catch{}try{const r=await fetch(new URL('./audio/voice/manifest.json',self.location.href));if(r.ok){const data=await r.json(),cache=await caches.open(CACHE);for(const file of data.files??[])if(/^v_[0-9a-f]{8}\.mp3$/.test(file)){try{await cache.add('./audio/voice/'+file);}catch{}}}}catch{}return self.skipWaiting();})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('astro-kitty-offline-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==location.origin)return;

  event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request,{ignoreSearch:event.request.mode==='navigate'}).then(cached=>cached||new Response('',{status:503}))));
});
